// ARR - Golden case: one fixed input and the shape the answer must have.
// Use an input that is safe to send: a test record, or the agent's test path.
return [{ json: {
  url: 'https://n8n.example.com/webhook/<agent path>',
  body: { message: 'What is the status of order 1001?' },
  expect: {
    status: 200,
    keys: ['output'],             // keys the response must have
    types: { output: 'string' },  // and their types
    contains: {},                 // { output: 'order' } : text the value must contain
    max_seconds: 60,
  },
} }];

// ARR - Golden case: compares the response with the expected shape in Golden case.
const c = $('Golden case').first().json;
const r = $input.first().json || {};
const exp = c.expect || {};
const problems = [];
const status = Number(r.statusCode || (r.error && r.error.httpCode) || 0);
if (exp.status && status !== exp.status) problems.push(`status ${status || 'none'}, expected ${exp.status}`);
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* plain text */ } }
if (Array.isArray(body)) body = body[0];
body = body || {};
for (const k of exp.keys || []) if (!(k in body)) problems.push(`missing key "${k}"`);
for (const [k, t] of Object.entries(exp.types || {})) if (k in body && typeof body[k] !== t) problems.push(`"${k}" is ${typeof body[k]}, expected ${t}`);
for (const [k, s] of Object.entries(exp.contains || {})) if (k in body && !String(body[k]).toLowerCase().includes(String(s).toLowerCase())) problems.push(`"${k}" does not contain "${s}"`);
if (problems.length) {
  const what = status ? 'the answer changed shape' : 'no answer from the agent';
  throw new Error(`ARR - Golden case failed, ${what}. ${problems.join('; ')}`);
}
return [{ json: { ok: true, status, keys: Object.keys(body) } }];
